    sourcePath,
    evidencePath: evidencePath || sourcePath,
    artifactPath: evidencePath || sourcePath,
    maturity: maturity || 'stable',
    declaration: {
      owner: 'kungfu',
      source: 'scripts/buildchain-kfd-evidence.mjs',
