// @ts-check

import { spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

const POLICY_SCHEMA =
  'https://xinfa.dev/schema/semantic-project-v1.schema.json';
const DEFAULT_SEMANTIC_PROJECT = '.xinfa/project.json';
const LIFECYCLES = new Set([
  'generated',
  'managed-block',
  'authored',
  'historical-append-only',
  'non-claim',
]);
const ROUTE_CAPABILITIES = [
  'value',
  'use',
  'authority',
  'constraints',
  'known-limits',
  'evidence',
  'next-action',
];
const AUTHORING_ACTIONS = {
  generated: {
    action: 'regenerate-and-dirty-check',
    review: 'machine',
    automatic: true,
  },
  'managed-block': {
    action: 'refresh-declared-managed-region',
    review: 'mixed',
    automatic: true,
  },
  authored: {
    action: 'review-authored-change',
    review: 'human',
    automatic: false,
  },
  'historical-append-only': {
    action: 'append-or-supersede-with-review',
    review: 'human',
    automatic: false,
  },
  'non-claim': {
    action: 'confirm-non-claim-boundary',
    review: 'human',
    automatic: false,
  },
};

/** @param {any} value @returns {any} */
function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(
    Object.keys(value)
      .sort()
      .map((key) => [key, canonical(value[key])]),
  );
}

/** @param {any} value @returns {string} */
function stableJson(value) {
  return `${JSON.stringify(canonical(value))}\n`;
}

/** @param {any} value @returns {string} */
function digest(value) {
  return `sha256:${crypto.createHash('sha256').update(stableJson(value)).digest('hex')}`;
}

// Public only for receipts assembled by the thin Shifu documentation CLI.
// Keeping one canonicalizer prevents adapter roots from drifting away from the
// inventory and authoring-impact roots owned by this module.
/** @param {any} value @returns {string} */
export function documentationSurfaceDigest(value) {
  return digest(value);
}

/** @param {Buffer} bytes @returns {string} */
function byteDigest(bytes) {
  return `sha256:${crypto.createHash('sha256').update(bytes).digest('hex')}`;
}

/** @param {any} value @param {string[]} required @param {string[]} optional @param {string} label */
function exactKeys(value, required, optional, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value))
    throw new Error(`${label} must be an object`);
  const allowed = new Set([...required, ...optional]);
  for (const key of Object.keys(value))
    if (!allowed.has(key)) throw new Error(`${label}.${key} is not declared`);
  for (const key of required)
    if (!(key in value)) throw new Error(`${label}.${key} is required`);
}

/** @param {unknown} value @param {string} label @returns {string} */
function repositoryPath(value, label) {
  if (
    typeof value !== 'string' ||
    !value ||
    path.posix.isAbsolute(value) ||
    path.win32.isAbsolute(value) ||
    value.includes('\\') ||
    value.split('/').includes('..') ||
    path.posix.normalize(value) !== value
  )
    throw new Error(`${label} must be an exact repository-relative POSIX path`);
  return value;
}

/** @param {string} root @returns {string[]} */
function trackedFiles(root) {
  const result = spawnSync('git', ['ls-files', '-z'], {
    cwd: root,
    encoding: 'buffer',
  });
  if (result.error || result.status !== 0)
    throw new Error(
      `cannot enumerate tracked surfaces: ${result.error?.message || result.stderr.toString('utf8')}`,
    );
  return result.stdout.toString('utf8').split('\0').filter(Boolean).sort();
}

/** @param {string} relative @param {any} selectors @returns {boolean} */
function matches(relative, selectors) {
  return (
    (selectors.paths || []).includes(relative) ||
    (selectors.prefixes || []).some((/** @type {string} */ prefix) =>
      relative.startsWith(prefix),
    ) ||
    (selectors.suffixes || []).some((/** @type {string} */ suffix) =>
      relative.endsWith(suffix),
    )
  );
}

/** @param {string} relative @param {any[]} classifications @returns {any} */
function classificationFor(relative, classifications) {
  return classifications.find((item) => matches(relative, item.selectors));
}

/** @param {string} root @param {string} relative */
function readSurface(root, relative) {
  const absolute = path.join(root, relative);
  const metadata = fs.lstatSync(absolute);
  if (metadata.isSymbolicLink() || !metadata.isFile())
    throw new Error(`${relative} must be a regular non-symlink file`);
  const bytes = fs.readFileSync(absolute);
  return {
    contentRoot: byteDigest(bytes),
    size: bytes.length,
  };
}

/** @param {any} policy @returns {Map<string, any>} */
function validatePolicy(policy) {
  exactKeys(
    policy,
    [
      '$schema',
      'schema',
      'project',
      'discovery',
      'classifications',
      'explicitSurfaces',
      'bindings',
      'routes',
      'compatibilityGates',
      'authority',
    ],
    [],
    'policy',
  );
  if (
    policy.$schema !== POLICY_SCHEMA ||
    policy.schema !== 'xinfa.semantic-project/v1'
  )
    throw new Error('unsupported documentation surface policy');
  exactKeys(
    policy.discovery,
    ['trackedOnly', 'extensions'],
    [],
    'policy.discovery',
  );
  if (policy.discovery.trackedOnly !== true)
    throw new Error('surface discovery must be limited to tracked files');
  if (
    !Array.isArray(policy.discovery.extensions) ||
    !policy.discovery.extensions.length
  )
    throw new Error('surface discovery requires extensions');
  const ids = new Set();
  for (const [index, item] of policy.classifications.entries()) {
    exactKeys(
      item,
      [
        'id',
        'lifecycle',
        'documentProfile',
        'verificationProfile',
        'visibility',
        'owner',
        'waiver',
        'selectors',
      ],
      [],
      `policy.classifications[${index}]`,
    );
    if (ids.has(item.id))
      throw new Error(`duplicate classification: ${item.id}`);
    ids.add(item.id);
    if (!LIFECYCLES.has(item.lifecycle))
      throw new Error(`unsupported lifecycle: ${item.lifecycle}`);
    if (typeof item.owner !== 'string' || !item.owner)
      throw new Error(`classification ${item.id} requires an owner`);
    if (item.waiver !== null)
      throw new Error(`classification ${item.id} has an unsupported waiver`);
    exactKeys(
      item.selectors,
      [],
      ['paths', 'prefixes', 'suffixes'],
      `policy.classifications[${index}].selectors`,
    );
    if (!Object.values(item.selectors).some((values) => values?.length))
      throw new Error(`classification ${item.id} has no selectors`);
  }
  for (const [index, route] of policy.routes.entries()) {
    exactKeys(
      route,
      [
        'id',
        'audience',
        'parityGroup',
        'entrypoints',
        'capabilities',
        'resolution',
        'selection',
      ],
      [],
      `policy.routes[${index}]`,
    );
  }
  const compatibilityIds = new Set();
  for (const [index, gate] of policy.compatibilityGates.entries()) {
    exactKeys(
      gate,
      [
        'id',
        'legacyEntrypoint',
        'status',
        'owner',
        'preservedCapabilities',
        'canonicalEntrypoints',
        'sunsetCondition',
      ],
      [],
      `policy.compatibilityGates[${index}]`,
    );
    if (compatibilityIds.has(gate.id))
      throw new Error(`duplicate compatibility gate: ${gate.id}`);
    compatibilityIds.add(gate.id);
    if (gate.status !== 'composed')
      throw new Error(`compatibility gate ${gate.id} must be composed`);
    if (!gate.preservedCapabilities.length || !gate.canonicalEntrypoints.length)
      throw new Error(`compatibility gate ${gate.id} is incomplete`);
  }
  return new Map(
    policy.classifications.map((/** @type {any} */ item) => [item.id, item]),
  );
}

/** @param {{root: string, policyRef?: string, files?: string[] | null}} options */
export function buildHumanSurfaceInventory({
  root,
  policyRef = DEFAULT_SEMANTIC_PROJECT,
  files = null,
}) {
  const policyPath = path.resolve(root, policyRef);
  const policy = JSON.parse(fs.readFileSync(policyPath, 'utf8'));
  const classifications = validatePolicy(policy);
  const candidates = (files || trackedFiles(root)).filter((relative) =>
    policy.discovery.extensions.some((/** @type {string} */ extension) =>
      relative.endsWith(extension),
    ),
  );
  /** @type {any[]} */
  const entries = [];
  const unclassified = [];
  for (const relative of candidates) {
    const classification = classificationFor(relative, policy.classifications);
    if (!classification) {
      unclassified.push(relative);
      continue;
    }
    entries.push({
      id: `file:${relative}`,
      path: relative,
      kind: 'document-file',
      classification: classification.id,
      lifecycle: classification.lifecycle,
      documentProfile: classification.documentProfile,
      verificationProfile: classification.verificationProfile,
      visibility: classification.visibility,
      owner: classification.owner,
      waiver: classification.waiver,
      ...readSurface(root, relative),
    });
  }
  for (const [index, surface] of policy.explicitSurfaces.entries()) {
    exactKeys(
      surface,
      ['id', 'path', 'kind', 'classification'],
      [],
      `policy.explicitSurfaces[${index}]`,
    );
    const relative = repositoryPath(
      surface.path,
      `explicit surface ${surface.id}`,
    );
    const classification = classifications.get(surface.classification);
    if (!classification)
      throw new Error(
        `unknown explicit classification: ${surface.classification}`,
      );
    entries.push({
      id: `explicit:${surface.id}`,
      path: relative,
      kind: surface.kind,
      classification: classification.id,
      lifecycle: classification.lifecycle,
      documentProfile: classification.documentProfile,
      verificationProfile: classification.verificationProfile,
      visibility: classification.visibility,
      owner: classification.owner,
      waiver: classification.waiver,
      ...readSurface(root, relative),
    });
  }
  entries.sort((left, right) =>
    left.id < right.id ? -1 : left.id > right.id ? 1 : 0,
  );
  const entryIds = new Set();
  for (const entry of entries) {
    if (entryIds.has(entry.id))
      throw new Error(`duplicate surface: ${entry.id}`);
    entryIds.add(entry.id);
  }
  if (unclassified.length)
    throw new Error(`unclassified human surfaces: ${unclassified.join(', ')}`);
  for (const route of policy.routes) {
    for (const entrypoint of route.entrypoints) {
      const relative = repositoryPath(
        entrypoint,
        `route ${route.id} entrypoint`,
      );
      if (!entries.some((entry) => entry.path === relative))
        throw new Error(
          `route ${route.id} has an unknown entrypoint: ${relative}`,
        );
    }
    for (const selected of route.selection.paths || []) {
      const relative = repositoryPath(
        selected,
        `route ${route.id} selected path`,
      );
      if (!entries.some((entry) => entry.path === relative))
        throw new Error(
          `route ${route.id} selects an unknown surface: ${relative}`,
        );
    }
  }
  const policyRoot = digest(policy);
  const bindings = policy.bindings.map(
    (/** @type {any} */ binding, /** @type {number} */ index) => {
      exactKeys(
        binding,
        [
          'id',
          'documentPath',
          'targetId',
          'targetKind',
          'targetPath',
          'relation',
          'expectedRevision',
        ],
        [],
        `policy.bindings[${index}]`,
      );
      const documentPath = repositoryPath(
        binding.documentPath,
        `binding ${binding.id} documentPath`,
      );
      if (!entries.some((entry) => entry.path === documentPath))
        throw new Error(
          `binding ${binding.id} references an unknown document surface`,
        );
      const targetPath = repositoryPath(
        binding.targetPath,
        `binding ${binding.id} targetPath`,
      );
      const target = readSurface(root, targetPath);
      return {
        ...binding,
        documentPath,
        targetPath,
        observedRevision: target.contentRoot,
        size: target.size,
      };
    },
  );
  const bindingIds = new Set();
  for (const binding of bindings) {
    if (bindingIds.has(binding.id))
      throw new Error(`duplicate binding: ${binding.id}`);
    bindingIds.add(binding.id);
  }
  bindings.sort((/** @type {any} */ left, /** @type {any} */ right) =>
    left.id < right.id ? -1 : left.id > right.id ? 1 : 0,
  );
  const providerPaths = new Set([
    ...entries.map((entry) => entry.path),
    ...bindings.map((/** @type {any} */ binding) => binding.targetPath),
  ]);
  const inventoryRoot = digest({
    policyRoot,
    entries: entries.map(
      ({
        id,
        path: source,
        kind,
        classification,
        lifecycle,
        visibility,
        owner,
        waiver,
        contentRoot,
        size,
      }) => ({
        id,
        path: source,
        kind,
        classification,
        lifecycle,
        visibility,
        owner,
        waiver,
        contentRoot,
        size,
      }),
    ),
    bindings,
  });
  return {
    schema: 'shifu.documentation-surface-inventory/v1',
    project: policy.project,
    policy: { reference: policyRef, root: policyRoot },
    inventoryRoot,
    closure: {
      discovered: candidates.length,
      explicit: policy.explicitSurfaces.length,
      classified: entries.length,
      unclassified: 0,
      humanSurfacePaths: new Set(entries.map((entry) => entry.path)).size,
      exactProviderPaths: providerPaths.size,
    },
    lifecycles: Object.fromEntries(
      [...LIFECYCLES]
        .sort()
        .map((lifecycle) => [
          lifecycle,
          entries.filter((entry) => entry.lifecycle === lifecycle).length,
        ]),
    ),
    entries,
    bindings,
    routes: policy.routes,
    compatibilityGates: policy.compatibilityGates,
    parityGroups: [
      ...new Set(
        policy.routes.map((/** @type {any} */ route) => route.parityGroup),
      ),
    ]
      .sort()
      .map((group) => ({
        id: group,
        audiences: ['agent', 'human'],
        capabilities: [...ROUTE_CAPABILITIES],
        nodeSet: 'shared',
      })),
  };
}

/** @param {string} root @param {string[]} args @returns {Buffer} */
function gitBytes(root, args) {
  const result = spawnSync('git', args, { cwd: root, encoding: 'buffer' });
  if (result.error || result.status !== 0)
    throw new Error(
      `git ${args.join(' ')} failed: ${result.error?.message || result.stderr.toString('utf8')}`,
    );
  return result.stdout;
}

/** @param {{root:string, since:string, policyRef?:string, inventory?:any}} options */
export function documentationAuthoringImpact({
  root,
  since,
  policyRef = DEFAULT_SEMANTIC_PROJECT,
  inventory = null,
}) {
  if (!since) throw new Error('documentation authoring impact requires since');
  const current = inventory || buildHumanSurfaceInventory({ root, policyRef });
  const policy = JSON.parse(
    fs.readFileSync(path.resolve(root, policyRef), 'utf8'),
  );
  validatePolicy(policy);
  const sourceRevision = gitBytes(root, ['rev-parse', `${since}^{commit}`])
    .toString('utf8')
    .trim();
  const headRevision = gitBytes(root, ['rev-parse', 'HEAD'])
    .toString('utf8')
    .trim();
  const changed = new Map();
  const tokens = gitBytes(root, [
    'diff',
    '--no-renames',
    '--name-status',
    '-z',
    sourceRevision,
    '--',
  ])
    .toString('utf8')
    .split('\0')
    .filter(Boolean);
  for (let index = 0; index < tokens.length; ) {
    const token = tokens[index++];
    const tab = token.indexOf('\t');
    const status = tab === -1 ? token : token.slice(0, tab);
    const source = tab === -1 ? tokens[index++] : token.slice(tab + 1);
    if (source) changed.set(source, status[0]);
  }
  for (const source of gitBytes(root, [
    'ls-files',
    '--others',
    '--exclude-standard',
    '-z',
  ])
    .toString('utf8')
    .split('\0')
    .filter(Boolean))
    changed.set(source, 'A');

  const explicit = new Map(
    policy.explicitSurfaces.map((/** @type {any} */ surface) => [
      surface.path,
      surface,
    ]),
  );
  const currentByPath = new Map(
    current.entries.map((/** @type {any} */ entry) => [entry.path, entry]),
  );
  const classifications = new Map(
    policy.classifications.map((/** @type {any} */ item) => [item.id, item]),
  );
  const obligations = [];
  const violations = [];
  for (const [source, change] of [...changed.entries()].sort(
    ([left], [right]) => left.localeCompare(right, 'en'),
  )) {
    const declared = currentByPath.get(source);
    const explicitSurface = explicit.get(source);
    const eligible =
      Boolean(explicitSurface) ||
      policy.discovery.extensions.some((/** @type {string} */ extension) =>
        source.endsWith(extension),
      );
    if (!eligible) continue;
    const classification = declared
      ? classifications.get(declared.classification)
      : explicitSurface
        ? classifications.get(explicitSurface.classification)
        : classificationFor(source, policy.classifications);
    if (!classification) {
      violations.push({ code: 'unclassified-surface', path: source });
      continue;
    }
    const lifecycle = /** @type {keyof typeof AUTHORING_ACTIONS} */ (
      classification.lifecycle
    );
    const mode = AUTHORING_ACTIONS[lifecycle];
    const obligation = {
      path: source,
      change,
      classification: classification.id,
      lifecycle: classification.lifecycle,
      owner: classification.owner,
      verificationProfile: classification.verificationProfile,
      requiredAction: mode.action,
      review: mode.review,
      automatic: mode.automatic,
      claimImpact:
        classification.lifecycle === 'non-claim' ? 'none' : 'evaluate',
    };
    obligations.push(obligation);
    if (change === 'D' && classification.lifecycle === 'historical-append-only')
      violations.push({
        code: 'historical-surface-deleted',
        path: source,
      });
  }
  const reviewRequired = obligations.some(
    (item) => item.review === 'human' || item.review === 'mixed',
  );
  const verdict = violations.length
    ? 'fail'
    : reviewRequired
      ? 'review-required'
      : 'pass';
  const receipt = {
    schema: 'shifu.documentation-authoring-impact/v1',
    verdict,
    qualifying: false,
    bounded: true,
    source: {
      since,
      revision: sourceRevision,
      head: headRevision,
      dirty: headRevision === sourceRevision ? obligations.length > 0 : null,
    },
    inventoryRoot: current.inventoryRoot,
    obligations,
    violations,
    compatibilityGates: current.compatibilityGates,
    summary: {
      affectedSurfaces: obligations.length,
      automatic: obligations.filter((item) => item.automatic).length,
      humanOrMixedReview: obligations.filter(
        (item) => item.review === 'human' || item.review === 'mixed',
      ).length,
      violations: violations.length,
    },
  };
  return { ...receipt, impactRoot: digest(receipt) };
}

export { POLICY_SCHEMA };

// SPDX-License-Identifier: Apache-2.0
// @ts-check

import fs from 'node:fs';
import path from 'node:path';

import { executeGateRun, validateGateReceipt } from './shifu-gate-executor.mjs';
import { buildGatePlan, loadGateRegistry } from './shifu-gate-runtime.mjs';

const CONTRACT = path.join('docs', 'shifu', 'gate-contract.json');
/** @type {Record<string, string>} */
const SCHEMAS = {
  registry: path.join(
    'docs',
    'shifu',
    'schema',
    'gate-registry-v1.schema.json',
  ),
  plan: path.join('docs', 'shifu', 'schema', 'gate-plan-v1.schema.json'),
  receipt: path.join('docs', 'shifu', 'schema', 'gate-receipt-v1.schema.json'),
};

/** @typedef {{write:(chunk:any)=>any}} Writer */
/** @typedef {{code:string, path:string, message:string}} GateIssue */

export function gateHelp() {
  return `shifu gate — inspect, plan, execute and validate project gates through one control plane
  gate contract                         print the canonical Gate contract
  gate schema <registry|plan|receipt>   print a canonical JSON Schema
  gate validate [--registry FILE|-] [--json]
                                        validate syntax, ids, dependencies, cycles and profiles
  gate list [--registry FILE] [--json]  list registered gates
  gate show GATE [--registry FILE] [--json]
                                        show one gate declaration
  gate explain GATE [--profile PROFILE] [--registry FILE] [--json]
                                        explain purpose, dependencies, documentation and policy
  gate matrix [--registry FILE] [--json]
                                        show every gate against every explicit profile decision
  gate plan PROFILE [--include-advisory] [--gate GATE] [--platform PLATFORM]
                    [--registry FILE] [--json]
                                        produce a deterministic dependency and platform plan
  gate run GATE... [--capability CAP] [--execution-context JSON] [--registry FILE] [--receipt FILE] [--json]
  gate run --profile PROFILE [--include-advisory] [--capability CAP]
           [--registry FILE] [--receipt FILE] [--json]
                                        execute a dependency closure and emit one unified receipt
  gate receipt validate FILE [--registry FILE] [--json]
                                        revalidate source, registry, definitions and action coverage

Registry discovery: --registry, then SHIFU_GATE_REGISTRY, then shifu.gates.json.
Every profile must explicitly decide every gate as required, advisory, or off.
Explicit gate runs are diagnostic and never qualifying. Only a complete profile
run at a clean source SHA can issue a qualifying receipt. Child actions use
structured argv and Shifu adds SHIFU_GATE_* evidence pointers; receipt output
never captures command output or the inherited environment.`;
}

/** @param {unknown} value @param {Writer} stdout */
function printJson(value, stdout) {
  stdout.write(`${JSON.stringify(value, null, 2)}\n`);
}

/** @param {string[]} argv */
function extractCommon(argv) {
  const rest = [];
  let registry = '';
  let json = false;
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === '--json') json = true;
    else if (arg === '--registry') {
      registry = argv[index + 1] || '';
      if (!registry) throw new Error('--registry requires FILE or -');
      index += 1;
    } else rest.push(arg);
  }
  return { rest, registry, json };
}

/** @param {string} root @param {string} registryRef @returns {any} */
function loadValid(root, registryRef) {
  const loaded = loadGateRegistry(root, registryRef);
  if (loaded.issues.length) {
    const first = loaded.issues[0];
    throw new Error(
      `gate registry is invalid: ${first.path || '/'} ${first.message} (${loaded.issues.length} issue${loaded.issues.length === 1 ? '' : 's'})`,
    );
  }
  return loaded;
}

/** @param {any} loaded */
function registryIdentity(loaded) {
  return {
    ref: loaded.ref,
    digest: loaded.digest,
    projectId: loaded.registry.project.id,
  };
}

/** @param {string} root @param {string} ref */
function receiptRegistryRef(root, ref) {
  if (ref === '-') return '<stdin-registry>';
  const relative = path.relative(root, path.resolve(root, ref));
  if (!relative || (!relative.startsWith('..') && !path.isAbsolute(relative)))
    return (relative || path.basename(ref)).split(path.sep).join('/');
  return '<external-registry>';
}

/** @param {any} registry @param {string} id */
function gateById(registry, id) {
  const gates = /** @type {any[]} */ (registry.gates);
  const gate = gates.find((item) => item.id === id);
  if (!gate) throw new Error(`unknown gate: ${id}`);
  return gate;
}

/** @param {any} registry @param {string} id */
function profileById(registry, id) {
  const profiles = /** @type {any[]} */ (registry.profiles);
  const profile = profiles.find((item) => item.id === id);
  if (!profile) throw new Error(`unknown gate profile: ${id}`);
  return profile;
}

/** @param {any} registry @param {any} loaded @param {any} gate @param {string} [profileId] */
function detail(registry, loaded, gate, profileId = '') {
  const decisions = Object.fromEntries(
    [...registry.profiles]
      .sort((a, b) => a.id.localeCompare(b.id))
      .map((profile) => [profile.id, profile.decisions[gate.id]]),
  );
  return {
    schema: 'shifu.gate-detail/v1',
    registry: registryIdentity(loaded),
    gate,
    profile: profileId
      ? {
          id: profileId,
          decision: profileById(registry, profileId).decisions[gate.id],
        }
      : null,
    decisions,
  };
}

/** @param {any} value @param {Writer} stdout */
function humanDetail(value, stdout) {
  const gate = value.gate;
  stdout.write(`${gate.id}: ${gate.title}\n`);
  stdout.write(`${gate.summary}\n`);
  stdout.write(`category: ${gate.category}\n`);
  stdout.write(
    `cost: ${gate.cost.class} (timeout ${gate.cost.timeoutSeconds}s)\n`,
  );
  stdout.write(`platforms: ${gate.platforms.join(', ')}\n`);
  stdout.write(`runner: ${gate.runner.capabilities.join(', ') || 'none'}\n`);
  stdout.write(`dependencies: ${gate.dependencies.join(', ') || 'none'}\n`);
  stdout.write(`action: ${gate.action.kind}\n`);
  stdout.write(`receipt: ${gate.receipt.expectation}\n`);
  stdout.write(`documentation: ${gate.documentation}\n`);
  if (value.profile)
    stdout.write(
      `profile ${value.profile.id}: ${value.profile.decision.mode} — ${value.profile.decision.reason}\n`,
    );
  else {
    stdout.write('profiles:\n');
    for (const [id, decision] of Object.entries(value.decisions))
      stdout.write(`  ${id}: ${decision.mode} — ${decision.reason}\n`);
  }
}

/** @param {any} registry @param {any} loaded */
function matrixValue(registry, loaded) {
  const profiles = [...registry.profiles].sort((a, b) =>
    a.id.localeCompare(b.id),
  );
  return {
    schema: 'shifu.gate-matrix/v1',
    registry: registryIdentity(loaded),
    profiles: profiles.map(({ id, title }) => ({ id, title })),
    rows: [...registry.gates]
      .sort((a, b) => a.id.localeCompare(b.id))
      .map((gate) => ({
        id: gate.id,
        title: gate.title,
        costClass: gate.cost.class,
        documentation: gate.documentation,
        decisions: Object.fromEntries(
          profiles.map((profile) => [profile.id, profile.decisions[gate.id]]),
        ),
      })),
  };
}

/** @param {any} value @param {Writer} stdout */
function humanMatrix(value, stdout) {
  const profiles = /** @type {any[]} */ (value.profiles);
  const matrixRows = /** @type {any[]} */ (value.rows);
  const headers = ['gate', 'cost', ...profiles.map((profile) => profile.id)];
  const rows = matrixRows.map((row) => [
    row.id,
    row.costClass,
    ...profiles.map((profile) => row.decisions[profile.id].mode),
  ]);
  const widths = headers.map((header, index) =>
    Math.max(header.length, ...rows.map((row) => String(row[index]).length)),
  );
  /** @param {any[]} row */
  const line = (row) =>
    row.map((item, index) => String(item).padEnd(widths[index])).join('  ');
  stdout.write(`${line(headers)}\n`);
  stdout.write(`${widths.map((width) => '-'.repeat(width)).join('  ')}\n`);
  for (const row of rows) stdout.write(`${line(row)}\n`);
}

/** @param {string[]} argv */
function parsePlanArgs(argv) {
  let profile = '';
  let platform = null;
  let includeAdvisory = false;
  const explicitGates = [];
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    const value = () => {
      index += 1;
      if (index >= argv.length) throw new Error(`${arg} requires a value`);
      return argv[index];
    };
    if (arg === '--include-advisory') includeAdvisory = true;
    else if (arg === '--gate') explicitGates.push(value());
    else if (arg === '--platform') platform = value();
    else if (arg.startsWith('-'))
      throw new Error(`unknown gate plan option: ${arg}`);
    else if (!profile) profile = arg;
    else throw new Error(`unexpected gate plan argument: ${arg}`);
  }
  if (!profile) throw new Error('gate plan requires PROFILE');
  return { profile, platform, includeAdvisory, explicitGates };
}

/** @param {any} plan @param {Writer} stdout */
function humanPlan(plan, stdout) {
  stdout.write(
    `profile: ${plan.profile}; platform: ${plan.platform || 'all'}; qualifying: ${plan.qualifying}\n`,
  );
  if (plan.unsupported.length) {
    stdout.write('unsupported:\n');
    for (const item of plan.unsupported)
      stdout.write(`  ${item.id}: ${item.reason}\n`);
  }
  for (const group of plan.groups) {
    stdout.write(`group ${group.index}:\n`);
    for (const gate of group.gates)
      stdout.write(
        `  ${gate.id} [${gate.mode}, ${gate.cost.class}] (${gate.selectedBy.join(', ')})\n`,
      );
  }
  if (plan.skipped.length) {
    stdout.write('skipped:\n');
    for (const item of plan.skipped)
      stdout.write(`  ${item.id} [${item.mode}]: ${item.reason}\n`);
  }
}

/** @param {string[]} argv */
function parseRunArgs(argv) {
  let profile = '';
  let includeAdvisory = false;
  let receipt = '';
  let overwrite = false;
  let executionContext = null;
  const capabilities = [];
  const gates = [];
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    const value = () => {
      index += 1;
      if (index >= argv.length) throw new Error(`${arg} requires a value`);
      return argv[index];
    };
    if (arg === '--profile') profile = value();
    else if (arg === '--include-advisory') includeAdvisory = true;
    else if (arg === '--capability') capabilities.push(value());
    else if (arg === '--receipt') receipt = value();
    else if (arg === '--overwrite') overwrite = true;
    else if (arg === '--execution-context') {
      if (executionContext)
        throw new Error('--execution-context may be specified once');
      try {
        executionContext = JSON.parse(value());
      } catch (error) {
        throw new Error(
          `--execution-context requires valid JSON: ${error instanceof Error ? error.message : String(error)}`,
        );
      }
      if (
        !executionContext ||
        typeof executionContext !== 'object' ||
        Array.isArray(executionContext)
      )
        throw new Error('--execution-context must be a JSON object');
      const keys = Object.keys(executionContext).sort();
      const expected = [
        'effectiveParameters',
        'executionProfile',
        'policyDigest',
        'policyRef',
      ];
      if (keys.join('\0') !== expected.join('\0'))
        throw new Error('--execution-context has unknown or missing fields');
      if (
        typeof executionContext.executionProfile !== 'string' ||
        !executionContext.executionProfile
      )
        throw new Error('--execution-context.executionProfile is required');
      if (!/^sha256:[0-9a-f]{64}$/.test(executionContext.policyDigest))
        throw new Error('--execution-context.policyDigest is invalid');
      if (
        typeof executionContext.policyRef !== 'string' ||
        !executionContext.policyRef ||
        path.posix.isAbsolute(executionContext.policyRef) ||
        path.win32.isAbsolute(executionContext.policyRef) ||
        executionContext.policyRef.split(/[\\/]/).includes('..')
      )
        throw new Error(
          '--execution-context.policyRef must be repository-relative',
        );
      const parameters = executionContext.effectiveParameters;
      const parameterFields = [
        'budgetSeconds',
        'episodeProfile',
        'episodeTimeoutSeconds',
        'fuzzSecondsPerTarget',
        'reserveSeconds',
        'upstreamBudgetSeconds',
      ];
      if (
        !parameters ||
        typeof parameters !== 'object' ||
        Array.isArray(parameters) ||
        Object.keys(parameters).sort().join('\0') !== parameterFields.join('\0')
      )
        throw new Error(
          '--execution-context.effectiveParameters has unknown or missing fields',
        );
      for (const field of parameterFields.filter(
        (field) => field !== 'episodeProfile',
      ))
        if (!Number.isInteger(parameters[field]) || parameters[field] <= 0)
          throw new Error(
            `--execution-context.${field} must be a positive integer`,
          );
      if (
        typeof parameters.episodeProfile !== 'string' ||
        !parameters.episodeProfile
      )
        throw new Error('--execution-context.episodeProfile is required');
      if (
        parameters.reserveSeconds + parameters.upstreamBudgetSeconds >=
        parameters.budgetSeconds
      )
        throw new Error(
          '--execution-context reserve plus upstream must be below budget',
        );
    } else if (arg.startsWith('-'))
      throw new Error(`unknown gate run option: ${arg}`);
    else gates.push(arg);
  }
  if (profile && gates.length)
    throw new Error('gate run accepts either GATE ids or --profile, not both');
  if (!profile && !gates.length)
    throw new Error(
      'gate run requires one or more GATE ids or --profile PROFILE',
    );
  if (includeAdvisory && !profile)
    throw new Error('--include-advisory requires --profile PROFILE');
  if (overwrite && !receipt)
    throw new Error('--overwrite requires --receipt FILE');
  return {
    profile,
    includeAdvisory,
    receipt,
    overwrite,
    executionContext,
    capabilities,
    gates,
  };
}

/** @param {any} receipt @param {Writer} stdout */
function humanReceipt(receipt, stdout) {
  stdout.write(
    `gate run: ${receipt.status}; qualifying: ${receipt.qualifying}; source: ${receipt.source.sha || 'unavailable'}${receipt.source.dirty ? ' (dirty)' : ''}\n`,
  );
  for (const result of receipt.results)
    stdout.write(
      `  ${result.gateId}: ${result.status}${result.reason ? ` — ${result.reason}` : ''}\n`,
    );
  for (const item of receipt.unsupported)
    stdout.write(`  ${item.id}: unsupported — ${item.reason}\n`);
}

/** @param {string} root @param {string} file @param {any} value @param {boolean} overwrite */
function writeReceipt(root, file, value, overwrite) {
  const target = path.resolve(root, file);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  if (!overwrite && fs.existsSync(target))
    throw new Error(
      `receipt already exists: ${file} (use --overwrite to replace it)`,
    );
  const temporary = `${target}.tmp-${process.pid}`;
  fs.writeFileSync(temporary, `${JSON.stringify(value, null, 2)}\n`, {
    flag: 'wx',
  });
  fs.renameSync(temporary, target);
}

/**
 * @param {string[]} argv
 * @param {{root?:string, stdout?:Writer, stderr?:Writer}} [options]
 */
export async function runGateCommand(
  argv,
  {
    root = process.cwd(),
    stdout = process.stdout,
    stderr = process.stderr,
  } = {},
) {
  const sub = argv[0] || 'help';
  if (sub === 'contract' && argv.length === 1) {
    stdout.write(fs.readFileSync(path.join(root, CONTRACT)));
    return 0;
  }
  if (sub === 'schema' && argv.length === 2 && SCHEMAS[argv[1]]) {
    stdout.write(fs.readFileSync(path.join(root, SCHEMAS[argv[1]])));
    return 0;
  }
  if (sub === 'help' || sub === '-h' || sub === '--help') {
    stderr.write(`${gateHelp()}\n`);
    return 0;
  }
  const { rest, registry: registryRef, json } = extractCommon(argv.slice(1));
  if (sub === 'validate') {
    if (rest.length)
      throw new Error(`unexpected gate validate argument: ${rest[0]}`);
    /** @type {any} */
    let loaded;
    try {
      loaded = loadGateRegistry(root, registryRef);
    } catch (error) {
      loaded = {
        ref:
          registryRef || process.env.SHIFU_GATE_REGISTRY || 'shifu.gates.json',
        digest: null,
        registry: null,
        issues: [
          {
            code: 'registry-read',
            path: '',
            message: error instanceof Error ? error.message : String(error),
          },
        ],
      };
    }
    const value = {
      schema: 'shifu.gate-validation/v1',
      registry: { ref: loaded.ref, digest: loaded.digest },
      valid: loaded.issues.length === 0,
      issues: loaded.issues,
    };
    if (json) printJson(value, stdout);
    else if (value.valid)
      stdout.write(
        `valid gate registry: ${loaded.ref} (${loaded.registry.gates.length} gates, ${loaded.registry.profiles.length} profiles)\n`,
      );
    else {
      stderr.write(`invalid gate registry: ${loaded.ref}\n`);
      for (const item of value.issues)
        stderr.write(`  ${item.code} ${item.path || '/'}: ${item.message}\n`);
    }
    return value.valid ? 0 : 1;
  }

  const loaded = loadValid(root, registryRef);
  const registry = loaded.registry;
  if (sub === 'list') {
    if (rest.length)
      throw new Error(`unexpected gate list argument: ${rest[0]}`);
    const value = {
      schema: 'shifu.gate-list/v1',
      registry: registryIdentity(loaded),
      gates: [...registry.gates]
        .sort((a, b) => a.id.localeCompare(b.id))
        .map((gate) => ({
          id: gate.id,
          title: gate.title,
          category: gate.category,
          costClass: gate.cost.class,
          documentation: gate.documentation,
        })),
    };
    if (json) printJson(value, stdout);
    else
      for (const gate of value.gates)
        stdout.write(`${gate.id}\t${gate.costClass}\t${gate.title}\n`);
    return 0;
  }
  if (sub === 'show' || sub === 'explain') {
    const id = rest[0];
    if (!id) throw new Error(`gate ${sub} requires GATE`);
    let profileId = '';
    for (let index = 1; index < rest.length; index += 1) {
      if (rest[index] === '--profile') {
        profileId = rest[index + 1] || '';
        if (!profileId) throw new Error('--profile requires PROFILE');
        index += 1;
      } else throw new Error(`unknown gate ${sub} option: ${rest[index]}`);
    }
    const value = detail(registry, loaded, gateById(registry, id), profileId);
    if (json) printJson(value, stdout);
    else humanDetail(value, stdout);
    return 0;
  }
  if (sub === 'matrix') {
    if (rest.length)
      throw new Error(`unexpected gate matrix argument: ${rest[0]}`);
    const value = matrixValue(registry, loaded);
    if (json) printJson(value, stdout);
    else humanMatrix(value, stdout);
    return 0;
  }
  if (sub === 'plan') {
    const options = parsePlanArgs(rest);
    const plan = buildGatePlan(registry, options.profile, {
      ref: loaded.ref,
      digest: loaded.digest,
      includeAdvisory: options.includeAdvisory,
      explicitGates: options.explicitGates,
      platform: options.platform,
    });
    if (json) printJson(plan, stdout);
    else humanPlan(plan, stdout);
    return plan.ok ? 0 : 1;
  }
  if (sub === 'run') {
    const options = parseRunArgs(rest);
    const safeRegistryRef = receiptRegistryRef(root, loaded.ref);
    const receipt = await executeGateRun(registry, {
      root,
      registryRef: safeRegistryRef,
      registryDigest: loaded.digest,
      profile: options.profile,
      explicitGates: options.gates,
      includeAdvisory: options.includeAdvisory,
      capabilities: options.capabilities,
      executionContext: options.executionContext,
      writer: stderr,
    });
    if (options.receipt)
      writeReceipt(root, options.receipt, receipt, options.overwrite);
    if (json) printJson(receipt, stdout);
    else {
      humanReceipt(receipt, stdout);
      if (options.receipt) stdout.write(`receipt: ${options.receipt}\n`);
    }
    return receipt.ok ? 0 : 1;
  }
  if (sub === 'receipt') {
    if (rest[0] !== 'validate' || !rest[1] || rest.length !== 2)
      throw new Error('gate receipt requires: validate FILE');
    const receipt = JSON.parse(
      fs.readFileSync(path.resolve(root, rest[1]), 'utf8'),
    );
    const validation = {
      schema: 'shifu.gate-receipt-validation/v1',
      receipt: rest[1],
      ...validateGateReceipt(receipt, registry, {
        root,
        registryRef: receiptRegistryRef(root, loaded.ref),
        registryDigest: loaded.digest,
      }),
    };
    if (json) printJson(validation, stdout);
    else {
      stdout.write(
        `gate receipt: valid=${validation.valid} current=${validation.current} qualifying=${validation.qualifying}\n`,
      );
      for (const item of validation.issues)
        stderr.write(`  ${item.code} ${item.path}: ${item.message}\n`);
    }
    return validation.valid && validation.current && validation.qualifying
      ? 0
      : 1;
  }
  stderr.write(`${gateHelp()}\n`);
  return 2;
}

